function op28PaymentForm(kind,id){
  var e=(kind==='purchase'?state.purchases:state.expenses).find(x=>x.id===id);if(!e)return;
  var p=op28engine().installmentState(e,kind==='purchase'?state.purchasePayments:state.expensePayments);
  op28showModal(`<h2 id="modal-title">Registrar abono</h2><p class="modal-subtitle">${esc(kind==='purchase'?op28PurchaseReference(e):e.id)} · ${esc(e.supplier||e.description)}</p><form id="op28-payment-form" data-kind="${kind}" data-id="${esc(id)}"><div class="detail-grid"><div><label>Saldo registrado</label><strong>${op28currency(p.balanceCents)}</strong></div><div><label>Siguiente parcialidad</label><strong>${p.nextNumber} de ${e.term}</strong></div></div><div class="form-grid">${op28select('mode','Modalidad',op28engine().PAYMENT_MODES,'Recomendado','required')}${op28input('installmentsCovered','Parcialidades a cubrir',1,'number',`min="1" max="${p.remaining}" step="1" required`)}${op28input('date','Fecha del pago',op28today(),'date',`required max="${op28today()}" ${e.date?'min="'+e.date.slice(0,10)+'"':''}`)}${op28input('amount','Otro monto MXN','','number','min="0.01" step="0.01" disabled')}<div class="field wide"><label for="op28-notes">Comentario o referencia</label><textarea name="notes" id="op28-notes" rows="2"></textarea></div></div><div id="op28-payment-recommendation" class="info-box blue"></div><p class="muted">Este registro documenta un pago realizado. No inicia un cargo ni una transferencia bancaria.</p>${op28formFooter('Registrar abono')}</form>`);
  op28UpdateRecommendation();
}
function op28UpdateRecommendation(){
  var form=document.getElementById('op28-payment-form');if(!form)return;
  var e=(form.dataset.kind==='purchase'?state.purchases:state.expenses).find(x=>x.id===form.dataset.id),v=Object.fromEntries(new FormData(form)),input=form.elements.amount;
  input.disabled=v.mode!=='Otro monto';input.required=v.mode==='Otro monto';form.elements.installmentsCovered.disabled=v.mode==='Liquidar saldo';
  try{var r=op28engine().paymentRecommendation(e,form.dataset.kind==='purchase'?state.purchasePayments:state.expensePayments,{mode:v.mode,installmentsCovered:v.mode==='Liquidar saldo'?1:Number(v.installmentsCovered||1),amountCents:op28parseAmount(input.value)});document.getElementById('op28-payment-recommendation').innerHTML=`Importe recomendado: <strong>${op28currency(r.recommendedCents)}</strong> · ${r.installmentsCovered} parcialidad(es).<br>Las siguientes cuotas se recalculan sobre el saldo restante.`;}catch(error){document.getElementById('op28-payment-recommendation').textContent=error.message;}
}

