document.addEventListener('click',function(event){var el=event.target.closest('[data-op28]');if(!el)return;var a=el.dataset.op28,id=el.dataset.id,kind=el.dataset.kind;
  try{
    if(a==='detail')op28Detail(kind,id);
    else if(a==='purchase-new')op28PurchaseForm();
    else if(a==='purchase-docs'){if(!window.PurchaseDocs28?.open)throw new Error('El importador de documentos todavía no está disponible. Actualiza la página.');window.PurchaseDocs28.open({purchaseId:id||undefined,mode:'order'});}
    else if(a==='purchase-invoices'){window.PurchaseDocs28.open({purchaseId:id,mode:'invoice'});}
    else if(a==='purchase-invoices-draft'){op28CapturePurchase();window.PurchaseDocs28.open({purchaseId:op28draft.id||undefined,purchaseDraft:{...op28draft.data,items:op28draft.items},mode:'invoice'});}
    else if(a==='purchase-docs-draft'){if(!window.PurchaseDocs28?.open)throw new Error('El importador de documentos todavía no está disponible. Actualiza la página.');op28CapturePurchase();window.PurchaseDocs28.open({purchaseId:op28draft.id||undefined,purchaseDraft:{...op28draft.data,items:op28draft.items},mode:'order'});}
    else if(a==='receive-scan')op28ReceiveScan();
    else if(a==='receive-assign')op28ReceiveAssignScan();
    else if(a==='expense-new')op28ExpenseForm();
    else if(a==='edit'){if(kind==='purchase')op28PurchaseForm(id);else op28ExpenseForm(id);}
    else if(a==='payment')op28PaymentForm(kind,id);
    else if(a==='receive')op28ReceiveForm(id);
    else if(a==='credit-new')op28CreditForm(id,kind);
    else if(a==='credit-edit')op28CreditForm(null,null,id);
    else if(a==='page'){op28pages[kind]=Math.max(1,(op28pages[kind]||1)+Number(el.dataset.step));render();}
    else if(a==='clear'){op28filters[id]=id==='calendar'?{kind:'all',status:'pending'}:{};op28pages[id]=1;render();}
    else if(a==='export')op28Export(id);
    else if(a==='expense-category'){op28filters.expenses.category=id;op28pages.expenses=1;render();}
    else if(a==='expense-month'){op28filters.expenses.month=id;op28filters.expenses.year=op28filters.expenses.year||op28today().slice(0,4);op28pages.expenses=1;render();}
    else if(a==='cotejo'){op28showCotejo=!op28showCotejo;render();}
    else if(a==='stats-tab'){op28statsTab=id;op28pages.statistics=1;render();}
    else if(a==='purchase-line'){
      var form=document.getElementById('op28-purchase-form'),name=form.elements.lineName.value.trim(),qty=Number(form.elements.lineQty.value),cost=op28parseAmount(form.elements.lineCost.value),code=document.getElementById('op28-line-code').value.trim();
      if(!name||!Number.isSafeInteger(qty)||qty<=0||(cost!=null&&(!Number.isSafeInteger(cost)||cost<0))){op28formError(form,'Completa la descripción y una cantidad entera positiva. El costo puede quedar por confirmar.');return;}
      var product=op28PurchaseProduct({skuOrUpc:code});op28CapturePurchase();op28draft.items.push({name,skuOrUpc:code,...(product?{sku:product.sku}:{}),qty,unitCostCents:cost,totalCents:cost==null?null:Math.round(qty*cost)});op28RenderPurchaseForm();
    }else if(a==='purchase-remove'){if(op28draft.items[Number(id)]?.receivedQty>0)throw new Error('Conserva las partidas con recepciones registradas.');op28CapturePurchase();op28draft.items.splice(Number(id),1);op28RenderPurchaseForm();}
    else if(a==='purchase-date'){var form=document.getElementById('op28-purchase-form'),v=Object.fromEntries(new FormData(form)),rule=op28engine().creditRuleFor(state.creditRules,v.lender,v.instrument),r=op28engine().creditPreview(v.date,rule);if(r.paymentDate){form.elements.firstPaymentDate.value=r.paymentDate;document.getElementById('op28-purchase-date-result').textContent='Primer pago estimado: '+op28date(r.paymentDate)+'. Puedes editarlo.';}else document.getElementById('op28-purchase-date-result').textContent='Configura corte y pago para este dador e instrumento en Calendario.';}
    else if(a==='period-prev'||a==='period-next'){var f=op28filters[id],step=a==='period-prev'?-1:1,b=op28Bounds(id),date=new Date((f.anchor||op28today())+'T12:00:00Z');if(f.mode==='Mes')date.setUTCMonth(date.getUTCMonth()+step,1);else if(f.mode==='Año')date.setUTCFullYear(date.getUTCFullYear()+step);else if(f.mode==='Semana')date.setUTCDate(date.getUTCDate()+step*7);else if(f.mode==='Rango'){var length=Math.round((Date.parse(b.to)-Date.parse(b.from))/86400000)+1;date.setUTCDate(date.getUTCDate()+step*length);f.end=new Date(Date.parse(b.to)+step*length*86400000).toISOString().slice(0,10);}else date.setUTCDate(date.getUTCDate()+step);f.anchor=date.toISOString().slice(0,10);op28pages[id]=1;render();}
  }catch(error){toast(error.message,true);}
});

document.addEventListener('change',function(event){var el=event.target;
  if(el.dataset.op28Filter){var route=el.dataset.op28Filter;op28filters[route][el.dataset.key]=el.value;op28pages[route]=1;render();}
  if(el.id==='op28-catalog-select'){op28catalog=el.value;op28pages.catalogs=1;render();}
  if(el.closest('#op28-payment-form'))op28UpdateRecommendation();
  if(el.closest('#op28-credit-form'))op28UpdateCreditPreview();
  if(el.id==='op28-line-code'){var product=op28PurchaseProduct({skuOrUpc:el.value}),form=el.closest('form');if(product){form.elements.lineName.value=product.name;form.elements.lineCost.value=op28amountValue(product.costCents);}}
  if(el.matches('[data-p29-select],[data-p29-sku]'))op28SyncReceiveRow(el.closest('[data-op28-receive-line]'),el.matches('[data-p29-sku]'));
  if(el.matches('[data-p29-qty]'))op28UpdateReceiveSummary();
});

document.addEventListener('input',function(event){if(event.target.matches('[data-p29-qty]'))op28UpdateReceiveSummary();});
document.addEventListener('keydown',function(event){
  if(event.key!=='Enter'||event.target.id!=='op28-receive-scan')return;
  event.preventDefault();event.stopPropagation();
  try{op28ReceiveScan();}catch(error){op28ReceiveFeedback(error.message,true);}
});

document.addEventListener('submit',async function(event){var form=event.target;if(!form.id.startsWith('op28-'))return;event.preventDefault();var btn=form.querySelector('button[type="submit"]');if(btn?.disabled)return;if(!form.reportValidity())return;if(btn)btn.disabled=true;
  try{var v=Object.fromEntries(new FormData(form)),result,kind=form.dataset.kind,id=form.dataset.id;
    if(form.id==='op28-purchase-form'){op28CapturePurchase();var type=op28draft.id?'purchase.update':'purchase.create',payload={...op28draft.data,id:op28draft.id||undefined,items:op28draft.items};result=await ERP.command(type,payload,{command:{id:op28draft.commandId||(op28draft.commandId=ERP.makeId()),type,payload,workspace:ERP.workspace,revision:ERP.revision}});}
    else if(form.id==='op28-expense-form'){result=await ERP.command(id?'expense.update':'expense.create',{...v,id:id||undefined,amountCents:op28parseAmount(v.amount),term:Number(v.term)});}
    else if(form.id==='op28-payment-form'){result=await ERP.command(kind+'.payment',{entityId:id,date:v.date,notes:v.notes,mode:v.mode,installmentsCovered:Number(v.installmentsCovered||1),amountCents:op28parseAmount(v.amount)});}
    else if(form.id==='op28-credit-form'){result=await ERP.command('credit.save',{...v,active:true,cutoffDay:v.cutoffDay===''?null:Number(v.cutoffDay),paymentDay:v.paymentDay===''?null:Number(v.paymentDay)});}
    else if(form.id==='op28-catalog-form'){result=await ERP.command('catalog.add',{catalog:op28catalog,value:v.value});if(result?.ok){return;}}
    else if(form.id==='op28-receive-form'){var type='inventory.receivePurchase',payload={purchaseId:id,warehouseId:document.getElementById('op28-receive-warehouse').value,items:op28ReceivePayload(form),reason:v.reason};result=await ERP.command(type,payload,{command:{id:form.dataset.receiptRequestId||(form.dataset.receiptRequestId=ERP.makeId()),type,payload,workspace:ERP.workspace,revision:ERP.revision}});}
    if(result?.ok){op28closeModal();var savedId=id||result.result?.id;if(savedId&&(kind==='purchase'||kind==='expense'))op28Detail(kind,savedId);else closeDrawer();}
    else if(result)op28formError(form,result.error||result.message||'Revisa los datos indicados e inténtalo nuevamente.');
  }catch(error){op28formError(form,error.message);}finally{if(btn)btn.disabled=false;}
});

renderers.purchases=op28Purchases;renderers.expenses=op28Expenses;renderers.calendar=op28Calendar;
renderers.statistics=op28Statistics;renderers.bestsellers=op28BestSellers;renderers.catalogs=op28Catalogs;
